//! They are in abcjs's own units, where one step -- the distance from a staff
//! line to the space beside it -- is [`STEP`].

/// One glyph outline, drawn about its own origin.
pub struct Glyph {
    /// Used to name the glyph's `<defs>` entry, so each outline is written into
    /// a figure once however many times it is drawn.
    pub name: &'static str,
    pub path: &'static str,
    /// How much horizontal room the glyph wants, in glyph units.
    pub width: f64,
}

/// Line to neighbouring space, in glyph units. abcjs derives this from its font
/// size as `30 * 93 / 720`, and the outlines below are drawn to match.
pub const STEP: f64 = 3.875;

/// Line to next line: two steps.
pub const LINE_GAP: f64 = STEP * 2.0;

